"""Working out which ticket a statement line pays for."""

from typing import List, Optional

from ..models import TICKET_ISSUED, StatementLine, Ticket


def ticket_for_line(store, line: StatementLine) -> Optional[Ticket]:
    return store.tickets.get(line.account_ref)


def open_tickets_for_phone_and_amount(store, line: StatementLine) -> List[Ticket]:
    """Open tickets bought from the line's phone for exactly the line's amount."""
    return [ticket for ticket in store.tickets.values()
            if ticket.status == TICKET_ISSUED and ticket.phone == line.phone and ticket.fare_kes == line.amount_kes]

